const rawItems = typeof $input.all === 'function' ? $input.all() : (typeof $input.first === 'function' ? [$input.first()] : []);
const accounts = [];
for (const item of rawItems) {
  const payload = item && item.json !== undefined ? item.json : item;
  if (!payload) continue;
  const list = Array.isArray(payload) ? payload : (Array.isArray(payload.data) ? payload.data : [payload]);
  for (const candidate of list) {
    const record = candidate && candidate.json !== undefined ? candidate.json : candidate;
    if (record && record.id && (record.isStrategic === true || record.isStrategic === 'true')) {
      accounts.push({ json: record });
    }
  }
}
return accounts;

const safeNodeJson = (name) => {
  try {
    return typeof $ === 'function' ? $(name)?.first()?.json : undefined;
  } catch {
    return undefined;
  }
};
const splitAccount = safeNodeJson('4. Split Out Accounts');
const contextPayload = $json || {};
const customer = contextPayload.customer || splitAccount || contextPayload || {};
const customerId = customer.id || splitAccount?.id || contextPayload.customerId || null;
const customerName = customer.name || splitAccount?.name || 'Strategic Account';
const ownerId = customer.ownerId || customer.createdBy || splitAccount?.createdBy || splitAccount?.ownerId || null;

// 1. Engagement (0..100 or null)
const interactionsRaw = contextPayload.interactions !== undefined ? contextPayload.interactions : safeNodeJson('6. Fetch Customer Interactions');
let engagement = null;
const interactionItems = Array.isArray(interactionsRaw) ? interactionsRaw : (interactionsRaw?.items || interactionsRaw?.data || null);
if (Array.isArray(interactionItems) && interactionItems.length > 0) {
  engagement = Math.min(100, Math.round(30 + interactionItems.length * 15));
} else if (typeof interactionsRaw?.score === 'number') {
  engagement = Math.min(100, Math.max(0, Math.round(interactionsRaw.score)));
}

// 2. Feedback (normalized to 0..100 scale or null)
const feedbackRaw = contextPayload.feedback !== undefined ? contextPayload.feedback : safeNodeJson('8. Fetch Feedback History');
let feedback = null;
const feedbackItems = Array.isArray(feedbackRaw) ? feedbackRaw : (feedbackRaw?.items || feedbackRaw?.data || null);
if (Array.isArray(feedbackItems) && feedbackItems.length > 0) {
  let total = 0;
  let count = 0;
  for (const item of feedbackItems) {
    if (typeof item.score === 'number') {
      total += Math.min(100, Math.max(0, item.score));
      count++;
    } else if (typeof item.rating === 'number') {
      total += Math.min(100, Math.max(0, (item.rating / 5) * 100));
      count++;
    } else if (typeof item.nps === 'number') {
      total += Math.min(100, Math.max(0, item.nps * 10));
      count++;
    }
  }
  if (count > 0) {
    feedback = Math.min(100, Math.max(0, Math.round(total / count)));
  }
} else if (typeof feedbackRaw?.score === 'number') {
  feedback = Math.min(100, Math.max(0, Math.round(feedbackRaw.score)));
}

// 3. Open Issues (inverse health metric 0..100: more open issues lowers score; null when missing)
const issuesRaw = contextPayload.issues !== undefined ? contextPayload.issues : safeNodeJson('9. Fetch Open Issues and Renewals');
let openIssues = null;
let openCount = 0;
const issueItems = Array.isArray(issuesRaw) ? issuesRaw : (issuesRaw?.issues || issuesRaw?.items || issuesRaw?.data || null);
if (Array.isArray(issueItems)) {
  openCount = issueItems.filter((i) => !i.resolvedAt && ['OPEN', 'PENDING', 'IN_PROGRESS'].includes(String(i.status || 'OPEN').toUpperCase())).length;
  openIssues = Math.max(0, 100 - openCount * 25);
} else if (typeof issuesRaw?.openIssuesCount === 'number') {
  openCount = issuesRaw.openIssuesCount;
  openIssues = Math.max(0, 100 - openCount * 25);
} else if (typeof issuesRaw?.score === 'number') {
  openIssues = Math.min(100, Math.max(0, Math.round(issuesRaw.score)));
}

// 4. Follow-up completion (0..100 from actual completed executions / eligible executions; never counts ACTIVE as 50%)
const followUpRaw = contextPayload.followUps !== undefined ? contextPayload.followUps : safeNodeJson('7. Fetch Follow-up History');
let followUpCompletion = null;
const enrollments = Array.isArray(followUpRaw) ? followUpRaw : (followUpRaw?.items || followUpRaw?.data || null);
if (Array.isArray(enrollments) && enrollments.length > 0) {
  let completedCount = 0;
  let eligibleCount = 0;
  for (const enrollment of enrollments) {
    if (Array.isArray(enrollment.executions) && enrollment.executions.length > 0) {
      for (const exec of enrollment.executions) {
        const st = String(exec.status || '').toUpperCase();
        if (st === 'SKIPPED') continue;
        eligibleCount++;
        if (st === 'COMPLETED' || st === 'SUCCESS' || st === 'SENT') {
          completedCount++;
        }
      }
    } else {
      const st = String(enrollment.status || '').toUpperCase();
      if (st === 'CANCELLED') continue;
      eligibleCount++;
      if (st === 'COMPLETED' || st === 'SUCCESS') {
        completedCount++;
      }
    }
  }
  if (eligibleCount > 0) {
    followUpCompletion = Math.min(100, Math.max(0, Math.round((completedCount / eligibleCount) * 100)));
  }
} else if (typeof followUpRaw?.completionRate === 'number') {
  followUpCompletion = Math.min(100, Math.max(0, Math.round(followUpRaw.completionRate)));
}

const evidence = [];
if (engagement !== null) evidence.push(`Interactions: ${Array.isArray(interactionItems) ? interactionItems.length : 1} records (score ${engagement}/100)`);
if (feedback !== null) evidence.push(`Feedback: ${Array.isArray(feedbackItems) ? feedbackItems.length : 1} reviews (score ${feedback}/100)`);
if (openIssues !== null) evidence.push(`Open issues metric: ${openIssues}/100 (${openCount} open)`);
if (followUpCompletion !== null) evidence.push(`Follow-up completion: ${followUpCompletion}%`);

const missingData = [];
if (engagement === null) missingData.push('engagement');
if (feedback === null) missingData.push('feedback');
if (openIssues === null) missingData.push('openIssues');
if (followUpCompletion === null) missingData.push('followUpCompletion');
const hasSufficientData = missingData.length === 0;

return [{
  json: {
    customerId,
    customerName,
    ownerId,
    engagement,
    feedback,
    openIssues,
    followUpCompletion,
    evidence,
    missingData,
    hasSufficientData
  }
}];

const norm = $('6. Normalize Account Data').first().json;
const health = $('7. Call Backend Account Health API').first().json;
const customerId = norm.customerId;
const customerName = norm.customerName || 'Strategic Account';
const ownerId = norm.ownerId || null;
const snapshotId = health.snapshotId || health.id || null;

if (health.status === 'INSUFFICIENT_DATA' || !snapshotId) {
  return [{
    json: {
      customerId,
      customerName,
      ownerId,
      snapshotId,
      score: health.score ?? 0,
      status: health.status || 'INSUFFICIENT_DATA',
      recommendedActions: [],
      hasRiskOrOpportunity: false
    }
  }];
}

const rawAi = $json?.message?.content || $json?.text || $json;
let parsed = null;
try {
  parsed = typeof rawAi === 'string' ? JSON.parse(rawAi) : rawAi;
} catch {
  parsed = null;
}

const allowedTypes = ['CREATE_RETENTION_TASK', 'ESCALATE_RISK', 'SCHEDULE_REVIEW'];
const rawActions = Array.isArray(parsed?.recommendedActions) ? parsed.recommendedActions : [];
const validActions = rawActions.filter((a) => {
  if (!a || typeof a !== 'object' || !allowedTypes.includes(a.type)) return false;
  if (!Array.isArray(a.evidence) || a.evidence.length === 0) return false;
  return a.evidence.every((e) => e && e.customerId === customerId && e.snapshotId === snapshotId);
});

const isAtRisk = health.status === 'AT_RISK' || health.status === 'CRITICAL';
if (isAtRisk && validActions.length === 0) {
  validActions.push({
    type: 'CREATE_RETENTION_TASK',
    evidence: [{ customerId, snapshotId }]
  });
}

const hasRiskOrOpportunity = Boolean(isAtRisk || (validActions.length > 0 && parsed?.hasRiskOrOpportunity === true));
const summary = typeof parsed?.summary === 'string' && parsed.summary.trim()
  ? parsed.summary.trim()
  : `Account health is ${health.status} (score: ${health.score}/100).`;

return [{
  json: {
    customerId,
    customerName,
    ownerId,
    snapshotId,
    score: health.score,
    status: health.status,
    summary,
    recommendedActions: validActions,
    hasRiskOrOpportunity,
    priority: health.status === 'CRITICAL' ? 'CRITICAL' : 'HIGH',
    taskTitle: `Account Health ${health.status}: Follow up with ${customerName}`,
    taskDescription: `${summary} Evidence: ${(health.evidence || []).join('; ')}`
  }
}];
